INSERT INTO public.rx_presets (business_id, user_id, kind, name)
SELECT bu.business_id, bu.user_id, 'investigation', trim(t.name)
FROM public.business_users bu
CROSS JOIN unnest(string_to_array('CBC|ESR|CRP|Procalcitonin|Peripheral Blood Film (PBF)|Blood Group|Hb%|TC|DC|Platelet Count|Reticulocyte Count|Absolute Eosinophil Count (AEC)|RBS|FBS|2HABF|HbA1c|OGTT|Serum Creatinine|Blood Urea|BUN|Serum Uric Acid|Serum Electrolytes|Sodium (Na+)|Potassium (K+)|Chloride (Cl-)|Calcium|Magnesium|Phosphate|eGFR|ALT (SGPT)|AST (SGOT)|Serum Bilirubin|ALP|GGT|Serum Albumin|Total Protein|Lipid Profile|Total Cholesterol|Triglyceride|HDL|LDL|VLDL|TSH|FT3|FT4|Serum Iron|Ferritin|Vitamin B12|Folate|Vitamin D|Urine R/E|Urine C/S|Urine for Protein|Urine Albumin|Urine Sugar|Urine Ketone|Urine Pregnancy Test (UPT)|Stool R/E|Stool C/S|Stool for Occult Blood|Stool for Ova & Cyst|Sputum for AFB|GeneXpert MTB/RIF|Mantoux Test|Blood Culture|Urine Culture|Stool Culture|Wound Swab C/S|Dengue NS1|Dengue IgM|Dengue IgG|Malaria Parasite|ICT for Malaria|Widal Test|TyphiDot|Leptospira Serology|HBsAg|Anti-HCV|HIV I & II|VDRL|TPHA|COVID-19 RT-PCR|COVID-19 Antigen|PT|INR|APTT|D-Dimer|FDP|Serum Amylase|Serum Lipase|Troponin I|Troponin T|CK-MB|BNP|NT-proBNP|ECG|Echocardiography|Exercise Tolerance Test (ETT)|Holter Monitoring|Chest X-ray PA View|Chest X-ray AP View|X-ray Abdomen Erect|X-ray Abdomen Supine|X-ray KUB|X-ray Skull|X-ray Cervical Spine|X-ray Dorsal Spine|X-ray Lumbar Spine|X-ray Pelvis|X-ray Shoulder|X-ray Elbow|X-ray Wrist|X-ray Hand|X-ray Hip|X-ray Knee|X-ray Ankle|X-ray Foot|Ultrasonography Whole Abdomen|USG Lower Abdomen|USG KUB|USG Hepatobiliary System|USG Pelvis|Obstetric USG|Transvaginal USG (TVS)|Breast USG|Scrotal USG|Thyroid USG|CT Brain|CT Chest|CT Abdomen|CT KUB|CT Angiogram|MRI Brain|MRI Spine|MRI Knee|MRI Shoulder|Mammography|DEXA Scan|Upper GI Endoscopy|Colonoscopy|Sigmoidoscopy|Bronchoscopy|Cystoscopy|FNAC|Biopsy|Histopathology|Cytology|Pap Smear|HPV DNA Test|Semen Analysis|ABG|VBG|Peak Expiratory Flow Rate (PEFR)|Spirometry|Pulmonary Function Test (PFT)|EEG|EMG|NCV|Fundoscopy|Visual Field Test|OCT Eye|Serum Beta-hCG|PSA|CA-125|CEA|AFP|CA 19-9', '|')) AS t(name)
ON CONFLICT DO NOTHING;